import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# packet.ShowCredits{PlayerRuntimeID: 300, StatusType: packet.ShowCreditsStatusEnd}
FINISHED = bytes.fromhex("ac0202")

# generated by gophertunnel b8bd735:
# packet.ShowCredits{PlayerRuntimeID: 0x1_0000_0007, StatusType: packet.ShowCreditsStatusStart}
WIDE_ID = bytes.fromhex("878080801000")

GOLDENS = [
    pytest.param(
        v2225.ShowCreditsPacket(player_id=300, credits_state=v2225.ShowCreditsPacket.CreditsState.FINISHED),
        FINISHED,
        id="finished",
    ),
    pytest.param(
        v2225.ShowCreditsPacket(player_id=0x1_0000_0007, credits_state=v2225.ShowCreditsPacket.CreditsState.START),
        WIDE_ID,
        id="wide-id",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_show_credits_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_show_credits_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
